<script setup lang="ts">
import { reactive, ref } from "vue"; import { useRouter } from "vue-router"; import { ElMessage } from "element-plus";
import { UploadFilled } from "@element-plus/icons-vue"; import { knowledgeApi } from "../api/knowledge"; import type { KnowledgeCategory, KnowledgeUnit } from "../types";
const router=useRouter();const rows=ref<KnowledgeUnit[]>([]);const categories=ref<KnowledgeCategory[]>([]);const loading=ref(false);const query=ref("");const status=ref("");const categoryId=ref("");const createOpen=ref(false);const categoryOpen=ref(false);const uploadItem=ref<KnowledgeUnit|null>(null);const uploadFiles=ref<File[]>([]);const selected=ref<KnowledgeUnit[]>([]);const deleteOpen=ref(false);const createForm=reactive({title:"",category_id:"",tags:""});const categoryForm=reactive({category_id:"",name:"",description:"",sort_order:0});
async function load(){loading.value=true;try{const [page,cats]=await Promise.all([knowledgeApi.list({page:1,page_size:100,query:query.value,status:status.value,category_id:categoryId.value}),knowledgeApi.categories()]);rows.value=page.items;categories.value=cats}finally{loading.value=false}}void load();
async function create(){await knowledgeApi.create({title:createForm.title,category_id:createForm.category_id,tags:createForm.tags.split(",").map(x=>x.trim()).filter(Boolean)});ElMessage.success("知识草稿已创建");createOpen.value=false;await load()}
async function saveCategory(){await knowledgeApi.createCategory(categoryForm);ElMessage.success("分类已保存");Object.assign(categoryForm,{category_id:"",name:"",description:"",sort_order:0});await load()}
async function batchUpload(){if(!uploadItem.value)return;for(const file of uploadFiles.value)await knowledgeApi.uploadVersion(uploadItem.value.knowledge_id,file);ElMessage.success("已提交导入任务");uploadItem.value=null;uploadFiles.value=[];await load()}
async function bulk(action:"publish"|"disable"){for(const item of selected.value){if(action==="publish")await knowledgeApi.publish(item.knowledge_id);else await knowledgeApi.disable(item.knowledge_id)}await load()}
async function bulkDelete(){for(const item of selected.value)await knowledgeApi.remove(item.knowledge_id);deleteOpen.value=false;selected.value=[];await load()}
</script><template><el-card class="page-card"><template #header><div class="card-header"><span>知识台账</span><el-space><el-button @click="categoryOpen=true">分类管理</el-button><el-button type="primary" @click="createOpen=true">新建知识</el-button></el-space></div></template><el-space class="toolbar" wrap><el-input v-model="query" placeholder="搜索标题或 ID" clearable @keyup.enter="load"/><el-select v-model="categoryId" clearable placeholder="全部分类" style="width:180px"><el-option v-for="c in categories" :key="c.category_id" :label="c.name" :value="c.category_id"/></el-select><el-select v-model="status" clearable placeholder="全部状态" style="width:150px"><el-option value="draft" label="草稿"/><el-option value="published" label="已发布"/><el-option value="disabled" label="已停用"/><el-option value="archived" label="已归档"/></el-select><el-button @click="load">查询</el-button><el-button :disabled="!selected.length" @click="bulk('publish')">批量发布</el-button><el-button :disabled="!selected.length" @click="bulk('disable')">批量停用</el-button><el-button type="danger" :disabled="!selected.length" @click="deleteOpen=true">批量删除</el-button></el-space><el-table v-loading="loading" :data="rows" @selection-change="(v:KnowledgeUnit[])=>selected=v"><el-table-column type="selection" width="45"/><el-table-column prop="knowledge_id" label="知识 ID" min-width="220" show-overflow-tooltip/><el-table-column prop="title" label="标题" min-width="200"/><el-table-column prop="category_id" label="分类" width="150"/><el-table-column prop="status" label="状态" width="100"/><el-table-column label="标签" min-width="180"><template #default="s"><el-tag v-for="t in s.row.tags" :key="t" class="tag-gap">{{t}}</el-tag></template></el-table-column><el-table-column label="操作" width="170"><template #default="s"><el-button link @click="router.push('/knowledge/'+s.row.knowledge_id)">详情</el-button><el-button link @click="uploadItem=s.row;uploadFiles=[]">导入</el-button></template></el-table-column></el-table><el-dialog v-model="createOpen" title="新建知识"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="createForm.title"/></el-form-item><el-form-item label="分类"><el-select v-model="createForm.category_id" style="width:100%"><el-option v-for="c in categories.filter(x=>x.status==='active')" :key="c.category_id" :label="c.name" :value="c.category_id"/></el-select></el-form-item><el-form-item label="标签"><el-input v-model="createForm.tags" placeholder="多个标签用英文逗号分隔"/></el-form-item></el-form><template #footer><el-button @click="createOpen=false">取消</el-button><el-button type="primary" @click="create">创建</el-button></template></el-dialog><el-dialog :model-value="Boolean(uploadItem)" :title="'导入到 '+ (uploadItem?.title||'')" @close="uploadItem=null"><el-upload drag multiple :auto-upload="false" :on-change="(f:any)=>uploadFiles.push(f.raw)" :on-remove="(f:any)=>uploadFiles=uploadFiles.filter(x=>x!==f.raw)"><el-icon class="el-icon--upload"><upload-filled/></el-icon><div class="el-upload__text">拖拽或点击选择多个文件</div></el-upload><template #footer><el-button @click="uploadItem=null">取消</el-button><el-button type="primary" @click="batchUpload">提交</el-button></template></el-dialog><el-dialog v-model="categoryOpen" title="分类管理" width="760px"><el-form inline><el-input v-model="categoryForm.category_id" placeholder="分类 ID"/><el-input v-model="categoryForm.name" placeholder="名称"/><el-input-number v-model="categoryForm.sort_order"/><el-button type="primary" @click="saveCategory">新增</el-button></el-form><el-table :data="categories"><el-table-column prop="category_id" label="ID"/><el-table-column prop="name" label="名称"/><el-table-column prop="sort_order" label="排序" width="80"/><el-table-column prop="status" label="状态" width="90"/><el-table-column label="操作" width="90"><template #default="s"><el-button link type="danger" @click="knowledgeApi.deleteCategory(s.row.category_id).then(load)">删除</el-button></template></el-table-column></el-table></el-dialog><el-dialog v-model="deleteOpen" title="批量删除知识"><p>删除后内容和向量将立即清理，且不可恢复。</p><template #footer><el-button @click="deleteOpen=false">取消</el-button><el-button type="danger" @click="bulkDelete">删除</el-button></template></el-dialog></el-card></template>
